flarum.reg.addChunkModule('190', '208', 'linkrobins-support', 'forum/components/SupportComposePage');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/SupportShowPage');
flarum.reg.addChunkModule('993', '707', 'linkrobins-support', 'forum/components/SupportStatsModal');
flarum.reg.addChunkModule('458', '236', 'linkrobins-support', 'forum/components/SupportGuestPrompt');
flarum.reg.addChunkModule('458', '236', 'linkrobins-support', 'forum/components/SupportIndexSidebar');
flarum.reg.addChunkModule('458', '236', 'linkrobins-support', 'forum/components/SupportTicketRow');
flarum.reg.addChunkModule('190', '208', 'linkrobins-support', 'forum/utils/composer');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/TicketHeader');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/ReplyItem');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/TicketEventItem');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/SavedRepliesMenu');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/ReplyComposer');
flarum.reg.addChunkModule('907', '426', 'linkrobins-support', 'forum/components/AssignTicketModal');